test('invoiceTotals clamps total at zero', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 100 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 8500);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.total, 0);
});

