test('createInvoice rejects invalid discount', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: -5 }],
  }), { ok: false, error: 'DISCOUNT_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 105 }],
  }), { ok: false, error: 'DISCOUNT_INVALID' });

